// FunnelMutation represents an operation that mutates the Funnel nodes in the graph.
type FunnelMutation struct {
	config
	op                   Op
	typ                  string
	id                   *uuid.UUID
	name                 *string
	slug                 *string
	funnel_type          *string
	status               *string
	steps                *[]map[string]interface{}
	appendsteps          []map[string]interface{}
	landing_page_html    *string
	landing_page_css     *map[string]interface{}
	total_views          *int
	addtotal_views       *int
	total_submissions    *int
	addtotal_submissions *int
	conversion_rate      *float64
	addconversion_rate   *float64
	metadata             *map[string]interface{}
	published_at         *time.Time
	created_at           *time.Time
	updated_at           *time.Time
	clearedFields        map[string]struct{}
	tenant               *uuid.UUID
	clearedtenant        bool
	leads                map[uuid.UUID]struct{}
	removedleads         map[uuid.UUID]struct{}
	clearedleads         bool
	done                 bool
	oldValue             func(context.Context) (*Funnel, error)
	predicates           []predicate.Funnel
}

var _ ent.Mutation = (*FunnelMutation)(nil)

// funnelOption allows management of the mutation configuration using functional options.
type funnelOption func(*FunnelMutation)

// newFunnelMutation creates new mutation for the Funnel entity.
func newFunnelMutation(c config, op Op, opts ...funnelOption) *FunnelMutation {
	m := &FunnelMutation{
		config:        c,
		op:            op,
		typ:           TypeFunnel,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withFunnelID sets the ID field of the mutation.
func withFunnelID(id uuid.UUID) funnelOption {
	return func(m *FunnelMutation) {
		var (
			err   error
			once  sync.Once
			value *Funnel
		)
		m.oldValue = func(ctx context.Context) (*Funnel, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().Funnel.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withFunnel sets the old Funnel of the mutation.
func withFunnel(node *Funnel) funnelOption {
	return func(m *FunnelMutation) {
		m.oldValue = func(context.Context) (*Funnel, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

// Client returns a new `ent.Client` from the mutation. If the mutation was
// executed in a transaction (ent.Tx), a transactional client is returned.
func (m FunnelMutation) Client() *Client {
	client := &Client{config: m.config}
	client.init()
	return client
}

// Tx returns an `ent.Tx` for mutations that were executed in transactions;
// it returns an error otherwise.
func (m FunnelMutation) Tx() (*Tx, error) {
	if _, ok := m.driver.(*txDriver); !ok {
		return nil, errors.New("ent: mutation is not running in a transaction")
	}
	tx := &Tx{config: m.config}
	tx.init()
	return tx, nil
}

